async function (variables) {
    var userOnboardingAdminGrid = new GridWidget(variables.element, variables.dataSource);
    userOnboardingAdminGrid.columns = [
        { field: "State", type: "string", title: "[resource_shortdisplayname[requestState]]", width: 40, template: "<span class='k-icon #=UserOnboardingAdmin.iconStates[State]#'></span>" },
        { field: "email", type: "string", title: "[resource_shortdisplayname[userEmail]]", template: "#=JSON.parse(DataJson).fields[0].email#" },
        { field: "companyName", type: "string", title: "[resource_shortdisplayname[companyName]]", template: "#=JSON.parse(DataJson).fields[1].companyName#" },
        { field: "CreatedOn", type: "date", title: "[resource_shortdisplayname[requestDate]]", width: 80, format: "{0:" + type.dateFormat + "}" },
        { field: "CreatedBy", title: "[resource_shortdisplayname[CreatedBy]]", width: 100 },
        { field: "requestType", type: "string", title: "[resource_shortdisplayname[requestType]]", width: 150, template: "#=JSON.parse(DataJson).fields[2].requestType ? UserOnboardingAdmin.requestTypes[JSON.parse(DataJson).fields[2].requestType.value] : ''#" },
    ];
    userOnboardingAdminGrid.editable = false;
    userOnboardingAdminGrid.sortable = false;
    userOnboardingAdminGrid.filterable = false;
    userOnboardingAdminGrid.pageable = false;
    userOnboardingAdminGrid.groupable = false;
    userOnboardingAdminGrid.toolbar = "<button name='addUserOnboardingRequest'><span class='k-icon k-i-plus'></span>[resource_displayname[New]]</button>";
    variables.UserOnboardingAdminGrid = userOnboardingAdminGrid;
    return userOnboardingAdminGrid;
}
